`timescale 1ns/1ns
module top;
logic data=0,control='x;
wire q;
bufif1 #(2,3,4) g(q,data,control);
assign (weak1,weak0) q=1'b1;
initial begin
  #1;$display("first %b",q);
  #2;$display("L %b",q);data=1;
  #1;$display("H_pending %b",q);
  #2;$display("H %b",q);data=0;
  #1;data=1;
  #2;$display("pulse %b",q);control=1;data=0;
  #1;$display("on_pending %b",q);
  #3;$display("on %b",q);control=0;
  #1;$display("off_pending %b",q);
  #4;$display("off %b",q);control='z;
  #1;$display("z_pending %b",q);
  #2;$display("z %b",q);
end
endmodule

