module top;
logic data=0,control=1;wire q;
bufif1 #(2,3,4) g(q,data,control);
assign (weak1,weak0) q=1'b1;
initial begin #5;$display("settled %b",q);data=1;control='x;#1;$display("before %b",q);#2;$display("after %b",q);end
endmodule

